contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(bytes32 _txid) public {
        bool before = c.approvedToLog(address(this)); if (__ESBMC_reverted()) return;
        bool reverted;
        bool result;
        bool r = c.logRedeemed(_txid); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
            result = r;
        }
        bool afterStatus = c.approvedToLog(address(this)); if (__ESBMC_reverted()) return;
        assert(!reverted && result == before && afterStatus == before);
    }

    receive() external payable {}
}

