pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DepositLog c;

    function setUp() public {
        c = new DepositLog();
    }

    function _run(bytes32 _txid) internal {
        bool before;
        try c.approvedToLog(address(this)) returns (bool __r) { before = __r; } catch { return; }
        bool reverted;
        bool result;
        try c.logRedeemed(_txid) returns (bool r) {
            reverted = false;
            result = r;
        } catch {
            reverted = true;
        }
        bool afterStatus;
        try c.approvedToLog(address(this)) returns (bool __r) { afterStatus = __r; } catch { return; }
        assertTrue(!reverted && result == before && afterStatus == before);
    }

    function testFuzz_run(bytes32 _txid) public {
        _run(_txid);
    }

    receive() external payable {}
}
